function responseContent(value) {
  let body = value?.body ?? value;
  if (typeof body === 'string') {
    const dataLines = body.split('\n').filter((line) => line.startsWith('data:')).map((line) => line.slice(5).trim()).filter((line) => line && line !== '[DONE]');
    if (dataLines.length) {
      let combined = '';
      for (const line of dataLines) {
        try {
          const parsed = JSON.parse(line);
          combined += parsed.choices?.[0]?.delta?.content || parsed.choices?.[0]?.message?.content || '';
        } catch {}
      }
      if (combined) return combined;
    }
    return body;
  }
  return body?.choices?.[0]?.message?.content || body?.choices?.[0]?.text || '';
}
const data = $('Group Events').first().json;
const raw = responseContent($input.first()?.json || {});
const clean = String(raw || '').replace(/^\`\`\`(?:markdown|text)?/i, '').replace(/\`\`\`$/i, '').trim();
let text = clean;
if (!text) {
  const heading = data.run.edition === 'morning' ? '☀️ 科技情报早报' : '🌙 科技情报晚报';
  if (!data.events.length) {
