  }
}
return [{ json: { text, reportStatus: clean ? 'generated' : 'fallback' } }];

const text = String($input.first().json.text || '').trim();
const config = $('Group Events').first().json.context.config;
const delivery = config.delivery || {};
const maxLength = Math.max(800, Number(delivery.maxMessageLength || 3500));
const paragraphs = text.split(/\n\s*\n/).map((part) => part.trim()).filter(Boolean);
const chunks = [];
let current = '';
for (const paragraph of paragraphs) {
  if (!current) {
    current = paragraph;
  } else if ((current + '\n\n' + paragraph).length <= maxLength) {
    current += '\n\n' + paragraph;
  } else {
    chunks.push(current);
    current = paragraph;
  }
}
if (current) chunks.push(current);
if (!chunks.length) chunks.push('本次简报没有可发送内容。');
return chunks.map((chunk, index) => ({
  json: {
    part: index + 1,
    total: chunks.length,
    text: chunk,
    botUuid: delivery.botUuid,
    body: {
      target_type: delivery.targetType || 'group',
      target_id: delivery.targetId,
      message_chain: [{ type: 'Plain', text: chunk }],
    },
  },
}));

function usageOf(items) {
  let inputTokens = 0;
  let outputTokens = 0;
  for (const item of items) {
    const body = item.json?.body ?? item.json ?? {};
    inputTokens += Number(body.usage?.prompt_tokens || body.usage?.input_tokens || 0);
    outputTokens += Number(body.usage?.completion_tokens || body.usage?.output_tokens || 0);
  }
  return { inputTokens, outputTokens };
}
const results = $input.all().map((item) => item.json || {});
const deliveryResults = results.map((result) => result.body ?? result);
const successful = deliveryResults.length > 0 && deliveryResults.every((result) => Number(result.statusCode || 200) >= 200 && Number(result.statusCode || 200) < 300 && !result.error);
const data = $('Group Events').first().json;
const report = $('Format Report').first().json;
const usage = usageOf($('AI Analyze').all().concat($('AI Merge Events').all(), $('Generate Report').all()));
const errors = deliveryResults.filter((result) => result.error || (result.statusCode && Number(result.statusCode) >= 400)).map((result) => String(result.error || result.statusMessage || result.statusCode)).slice(0, 5);
return [{
  json: {
    runKey: data.run.runKey,
    edition: data.run.edition,
    startedAt: data.run.startedAt,
    completedAt: new Date().toISOString(),
    status: successful ? 'success' : 'delivery_failed',
    sourceCount: Array.isArray(data.context.sources) ? data.context.sources.filter((source) => source.enabled).length : 0,
    candidateCount: Number(data.candidateCount || 0),
    selectedCount: Number(data.events?.length || 0),
    llmCalls: $('AI Analyze').all().length + $('AI Merge Events').all().length + $('Generate Report').all().length,
    inputTokens: usage.inputTokens,
    outputTokens: usage.outputTokens,
    reportText: report.text || '',
    deliveryStatus: successful ? 'sent' : 'failed',
    errorSummary: errors.join('; '),
  },
}];
